    /// the match correspond to a word boundary.
    ///
    /// Note that the HIR returned is like turning `pat` into
    /// `(?m:^|\W)(pat)(?m:$|\W)`. That is, the true match is at capture group
    /// `1` and not `0`.
    pub(crate) fn into_word(self) -> Result<ConfiguredHIR, Error> {
